import hashlib, html, json, shutil, sys
from pathlib import Path
from urllib.parse import quote
from verify_china_order_release import IDS, PREFIX, verify

archive=Path(sys.argv[1])
by={r['id']:r for r in json.loads((archive/'manifest.json').read_text())['records']}
q=Path('research/china-watchlist-49-pending-documents-2026-11-20.json').read_bytes()
assert hashlib.sha1(b'blob '+str(len(q)).encode()+b'\0'+q).hexdigest()=='0f19c528d49ab5626d6de90da1d976c5833e7d84'
queue=json.loads(q)['records']
assert [r['artifact_record_id'] for r in queue]==IDS
media=Path(PREFIX);media.mkdir(parents=True,exist_ok=True)
e=html.escape
cards=[];receipt=[]
groups={'china':'Китайские марки','japan':'Японские марки','korea':'Корейские марки','europe':'Европейские марки'}
for num,old in enumerate(queue,1):
    ident=old['artifact_record_id'];r=by[ident]
    assert all(old[k]==r[k] for k in ('title','mileage_km','fob_usd','photo_url')),ident
    name=r['title'][5:]+' '+r['title'][:4]
    img=media/(ident+'.jpg');shutil.copyfile(archive/(ident+'.jpg'),img)
    receipt.append(dict(old,engine=r['engine'],brand_group=r['brand_group'],photo_path='/'+img.as_posix(),photo_sha256=hashlib.sha256(img.read_bytes()).hexdigest(),publication_approved=True,rights_confirmed=False,status='supplier_reference_only'))
    url='/podbor.html?similar='+quote(name+' · КИТАЙ')
    cards.append(f'<article class="cn-example" data-origin="{e(r["brand_group"])}" data-search="{e(name+" "+r["engine"],quote=True)}"><div class="cn-overline">{groups[r["brand_group"]]} · {num:02d} / 49</div><img src="/{img.as_posix()}" alt="{e(name,quote=True)}" loading="lazy" decoding="async" width="1000" height="750"><div class="cn-body"><h2>{e(name)}</h2><dl><div><dt>Двигатель</dt><dd>{e(r["engine"])}</dd></div><div><dt>Пробег по данным поставщика</dt><dd>{r["mileage_km"]:,} км</dd></div><div><dt>Цена FOB на 20.11.2026</dt><dd>{r["fob_usd"]:,} USD</dd></div></dl><p>Пример подбора. Наличие, мощность по документам, диагностику и итоговую цену уточняем перед заказом.</p><a class="button button-primary" href="{url}">Подобрать аналог</a></div></article>')
